460	  private _setProfileStops(
461	    stops: AboutLightsObjectOptions["profileStops"],
462	  ): void {
463	    if (!Array.isArray(stops)) {
464	      this._profileStops = [];
465	      this._profileKeys = [];
466	      return;
467	    }
468	    this._profileStops = stops
469	      .filter(
470	        (stop): stop is AboutLightProfileStop =>
471	          stop != null &&
472	          Number.isFinite(stop.progress) &&
473	          stop.values != null &&
474	          typeof stop.values === "object",
475	      )
476	      .map((stop) => ({
477	        progress: Math.max(0, Math.min(1, stop.progress)),
478	        values: { ...stop.values },
479	      }))
480	      .sort((a, b) => a.progress - b.progress);
481	    this._profileKeys = this._collectProfileKeys(this._profileStops);
482	  }
