484	  private _collectProfileKeys(stops: AboutLightProfileStop[]): string[] {
485	    const seen = new Set<string>();
486	    for (const stop of stops) {
487	      for (const key of Object.keys(stop.values)) {
488	        if (key === "travelProgress" || key === "intensity") continue;
489	        seen.add(key);
490	      }
491	    }
492	    return Array.from(seen);
