495	  private _applyProfileByProgress(): void {
496	    if (this._profileStops.length === 0) return;
497	    const sampled = this._sampleProfile(this._travelProgress);
498	    if (!sampled) return;
499	    const [left, right, t] = sampled;
500	    const keys = this._profileKeys;
501	    for (let i = 0; i < keys.length; i += 1) {
502	      const key = keys[i];
503	      const leftValue = left.values[key];
504	      const rightValue = right.values[key];
505	      if (
506	        !Number.isFinite(leftValue as number) &&
507	        !Number.isFinite(rightValue as number)
508	      ) {
509	        continue;
510	      }
511	      const l = Number.isFinite(leftValue as number)
512	        ? Number(leftValue)
513	        : Number(rightValue);
514	      const r = Number.isFinite(rightValue as number) ? Number(rightValue) : l;
515	      this._applyLightIntensityValue(key, l + (r - l) * t);
516	    }
517	  }
