519	  private _sampleProfile(
520	    progress: number,
521	  ): [AboutLightProfileStop, AboutLightProfileStop, number] | null {
522	    const stops = this._profileStops;
523	    if (stops.length === 0) return null;
524	    if (stops.length === 1) return [stops[0], stops[0], 0];
525	    const clamped = Math.max(0, Math.min(1, progress));
526	    if (clamped <= stops[0].progress) return [stops[0], stops[0], 0];
527	    const last = stops[stops.length - 1];
528	    if (clamped >= last.progress) return [last, last, 0];
529	    for (let index = 0; index < stops.length - 1; index += 1) {
530	      const left = stops[index];
531	      const right = stops[index + 1];
532	      if (clamped < left.progress || clamped > right.progress) continue;
533	      const span = Math.max(Number.EPSILON, right.progress - left.progress);
534	      return [left, right, (clamped - left.progress) / span];
535	    }
536	    return [last, last, 0];
537	  }
