573	      if (!light) continue;
574	      const rotateWithCamera = followOpts?.rotateWithCamera ?? true;
575	      const lightType = (spec.type ?? "directional").toLowerCase();
576	      const hasTarget = lightType === "directional" || lightType === "spot";
577	      const targetObj =
578	        hasTarget &&
579	        (light instanceof THREE.DirectionalLight ||
580	          light instanceof THREE.SpotLight)
581	          ? light.target
