601	                followOpts.targetOffset.y ?? 0,
602	                followOpts.targetOffset.z ?? 0,
603	              )
604	            : this._worldDeltaToOffset(
605	                targetObj.position.clone().sub(camPos),
606	                rotateWithCamera,
607	                camInvQuat,
608	              )
609	          : null;
610	
611	      this._followCameraEntries.push({
